const HEX_DIGITS = '0123456789abcdef';

function toHexPair(byte) {
  return `${HEX_DIGITS[(byte >> 4) & 0x0f]}${HEX_DIGITS[byte & 0x0f]}`;
}

export function toPythonBytesLiteral(buffer) {
  let result = "b'";

  for (const byte of buffer.values()) {
    if (byte === 0x09) {
      result += '\\t';
    } else if (byte === 0x0a) {
      result += '\\n';
    } else if (byte === 0x0d) {
      result += '\\r';
    } else if (byte === 0x27) {
      result += "\\'";
    } else if (byte === 0x5c) {
      result += '\\\\';
    } else if (byte >= 0x20 && byte <= 0x7e) {
      result += String.fromCharCode(byte);
    } else {
      result += `\\x${toHexPair(byte)}`;
    }
  }

  result += "'";
  return result;
}

