import { buildFixedBytes, buildInt8ul, buildInt16ul } from './construct-lite.mjs';
import { toPythonBytesLiteral } from './python-bytes.mjs';

function pythonModulo(value, divisor) {
  return ((value % divisor) + divisor) % divisor;
}

function buildOutputs(args) {
  const format1 = buildInt8ul(args.a);
  const format2 = buildInt16ul(args.b);
  const format3 = buildFixedBytes(args.d, Buffer.from(args.c, 'utf8'));
  const format4 = buildInt8ul(args.f);
  const format5 = buildFixedBytes(args.g, Buffer.from(args.e, 'utf8'));
  const format6 = buildInt8ul(pythonModulo(args.f + args.g, 256));
  const format7 = buildInt8ul(pythonModulo(args.a + args.b, 256));

  return [format1, format2, format3, format4, format5, format6, format7];
}

function writeLines(lines, stream) {
  for (const line of lines) {
    stream.write(`${line}\n`);
  }
}

export function main(argv = process.argv) {
  const parseResult = parseCommandLine(argv);

  if (parseResult.kind === 'help') {
    process.stdout.write(parseResult.output);
    return parseResult.exitCode;
