import {
  ARGUMENT_DEFINITIONS,
  ARGUMENTS_BY_NAME,
  formatHelp,
  formatUsage,
  getProgramName,
} from './cli-spec.mjs';

const DECIMAL_INTEGER_PATTERN = /^[+-]?\d(?:_?\d)*$/;
const NEGATIVE_NUMBER_PATTERN = /^-\d(?:_?\d)*(?:\.\d(?:_?\d)*)?$/;

function isNegativeNumberToken(token) {
  return NEGATIVE_NUMBER_PATTERN.test(token);
}

function looksLikeOptionToken(token) {
  return token.startsWith('-') && !isNegativeNumberToken(token);
}

function parseIntegerValue(optionName, rawValue) {
  if (!DECIMAL_INTEGER_PATTERN.test(rawValue)) {
    throw createCliError(`argument ${optionName}: invalid int value: '${rawValue}'`);
  }

  const normalized = rawValue.replace(/_/g, '');
  const parsed = Number(normalized);
  if (!Number.isInteger(parsed)) {
    throw createCliError(`argument ${optionName}: invalid int value: '${rawValue}'`);
  }

  return parsed;
}

function createCliError(message) {
  const error = new Error(message);
  error.name = 'CliParseError';
  return error;
}

function createResult(kind, programName, payload = {}) {
  return {
    kind,
    programName,
    ...payload,
  };
}

function collectUnknownTokenExtras(tokens, index, extras) {
  const token = tokens[index];
  extras.push(token);

  const hasInlineValue = token.includes('=');
  if (hasInlineValue) {
    return index;
  }

  const nextToken = tokens[index + 1];
  if (nextToken === undefined) {
    return index;
  }

  if (looksLikeOptionToken(nextToken)) {
    return index;
  }

  extras.push(nextToken);
  return index + 1;
}

