  if (definition.type === 'int') {
    return parseIntegerValue(definition.name, rawValue);
  }

  return rawValue;
}

export function parseCommandLine(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = Array.isArray(argv) ? argv.slice(2) : [];
  const parsedValues = {};
  const extras = [];

  try {
    for (let index = 0; index < tokens.length; index += 1) {
      const token = tokens[index];

      if (token === '-h' || token === '--help') {
        return createResult('help', programName, { output: formatHelp(programName), exitCode: 0 });
      }

      if (token.startsWith('--')) {
        const equalsIndex = token.indexOf('=');
        const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
        const definition = ARGUMENTS_BY_NAME[optionName];

        if (definition === undefined) {
          index = collectUnknownTokenExtras(tokens, index, extras);
          continue;
        }

        let rawValue;
        if (equalsIndex !== -1) {
          rawValue = token.slice(equalsIndex + 1);
        } else {
          const nextToken = tokens[index + 1];
          if (nextToken === undefined || looksLikeOptionToken(nextToken)) {
            throw createCliError(`argument ${optionName}: expected one argument`);
          }

          rawValue = nextToken;
          index += 1;
        }

        parsedValues[optionName] = coerceValue(definition, rawValue);
        continue;
      }

      if (token.startsWith('-')) {
        index = collectUnknownTokenExtras(tokens, index, extras);
        continue;
      }

      extras.push(token);
    }
  } catch (error) {
    if (error && error.name === 'CliParseError') {
      return createResult('error', programName, {
        output: `${formatUsage(programName)}\n${programName}: error: ${error.message}\n`,
        exitCode: 2,
      });
